import { test, expect } from '@playwright/test';
import { resetAndSeed } from '../support/seed';

// MUTATIVE (revises the discount rule and the discount-everywhere rule). An invoice discount may be
// either a percentage or a flat amount; either way it comes off before tax and is shown clearly.
// Updated copies of the discount specs ship in the sibling override folder.
test.describe('percentage or fixed discount', () => {
  test('a fixed-amount discount comes off before tax', { tag: '@functionality' }, async ({ page }) => {
    await resetAndSeed({
      clients: [{ id: 1, name: 'Acme Ltd', email: 'ops@acme.example' }],
      projects: [{ id: 1, name: 'Website Rebuild', clientId: 1 }],
      invoices: [{ id: 1, projectId: 1, status: 'DRAFT', discountAmount: 50, taxPct: 20, lineItems: [{ id: 1, description: 'Work', qty: 1, unitPrice: 200 }] }],
    });
    await page.goto('/');
    await page.getByTestId('nav-projects').click();
    await page.getByTestId('project-open-1').click();
    await page.getByTestId('invoice-open-1').click();

    await expect(page.getByTestId('invoice-subtotal')).toHaveText('$200.00');
    await expect(page.getByTestId('invoice-discount')).toHaveText('$50.00');
    await expect(page.getByTestId('invoice-taxable-base')).toHaveText('$150.00');
    await expect(page.getByTestId('invoice-tax')).toHaveText('$30.00'); // 20% of 150
    await expect(page.getByTestId('invoice-amount')).toHaveText('$180.00'); // 200 - 50 + 30
  });
});
import { existsSync, readFileSync } from 'node:fs';

// Read the known audit file — the second test-assertion channel alongside the UI. The app appends
// one record per line; /__test__/reset clears it per spec. Path comes from AUDIT_FILE (set by
// bin/start / bin/e2e); falls back to the app's default.
const AUDIT_FILE = process.env.AUDIT_FILE ?? '../.run/audit.log';

/** All audit records currently in the file, one per element (empty if none). */
export function auditLines(): string[] {
  return existsSync(AUDIT_FILE)
    ? readFileSync(AUDIT_FILE, 'utf8').split('\n').filter((l) => l.length > 0)
    : [];
}

// Usage in a spec (audit-category test):
//   expect(auditLines()).toContain('OWNER_CREATED id=1 name=Acme');
// Shared per-spec data setup. Each spec's beforeEach RESETS then SEEDS via the app's /__test__
// endpoint — this is Arrange, not Assert. Specs still ASSERT only through the UI (data-testid).
//
// FAIL LOUD: /__test__/reset and /__test__/seed are the Arrange for EVERY spec, so they are a hard
// precondition — if either does not return 2xx the data is not in the state the test assumes, and a
// silent failure would surface later as confusing, misattributed assertion failures on unrelated
// specs (e.g. leftover rows because reset could not clear an FK-referenced table). We throw here so
// the break is attributed to the seed contract, and so a developer running its own spec sees the
// broken endpoint immediately instead of shipping it.
import { request, type APIResponse } from '@playwright/test';

const BASE = process.env.BASE_URL ?? `http://localhost:${process.env.PORT ?? 3000}`;

async function must(res: Promise<APIResponse>, what: string): Promise<void> {
  const r = await res;
  if (!r.ok()) {
    const body = (await r.text().catch(() => '')).slice(0, 500);
    throw new Error(`seed contract broken: ${what} returned HTTP ${r.status()} — ${body}`);
  }
}

export async function resetAndSeed(fixture: unknown): Promise<void> {
  const api = await request.newContext({ baseURL: BASE });
  try {
    await must(api.post('/__test__/reset'), 'POST /__test__/reset');
    await must(api.post('/__test__/seed', { data: fixture }), 'POST /__test__/seed');
  } finally {
    await api.dispose();
  }
}

// Usage in a spec:
//   test.beforeEach(async () => { await resetAndSeed({ /* rows this spec needs */ }); });
-- An invoice can take a percentage off what its line items add up to. The stored amount remains what
-- is owed, so it is now the subtotal less the discount; existing invoices have no discount.
ALTER TABLE invoice ADD COLUMN discount_pct DECIMAL(5, 2) DEFAULT 0 NOT NULL;

ALTER TABLE invoice ADD CONSTRAINT invoice_discount_pct_range CHECK (discount_pct >= 0 AND discount_pct <= 100);
-- An invoice can also take a flat amount off what its line items add up to, on top of (or instead of)
-- the percentage discount. It never takes off more than is left after the percentage. Existing
-- invoices have no flat discount, so their amounts are unchanged.
ALTER TABLE invoice ADD COLUMN discount_amount DECIMAL(12, 2) DEFAULT 0 NOT NULL;

ALTER TABLE invoice ADD CONSTRAINT invoice_discount_amount_non_negative CHECK (discount_amount >= 0);
-- A single line item can take its own percentage off what it charges. The line's amount is then what it
-- charges less its discount, and the invoice is worked out from those discounted lines. Existing lines
-- have no discount, so no amounts change.
ALTER TABLE invoice_line_item ADD COLUMN discount_pct DECIMAL(5, 2) DEFAULT 0 NOT NULL;

ALTER TABLE invoice_line_item ADD CONSTRAINT invoice_line_item_discount_pct_range
    CHECK (discount_pct >= 0 AND discount_pct <= 100);
