217	    private BigDecimal sumOverTaxableLines(UnaryOperator<BigDecimal> perLine) {
218	        return lineItems.stream().filter(l -> !taxExempt && !l.isTaxExempt()).map(InvoiceLineItem::getAmount)
219	                .map(amount -> perLine.apply(amount.subtract(discountOn(amount))))
220	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
221	    }
222	
223	    /**
224	     * The part of a tax-inclusive price that is the given percentage, worked back out of it: the price
225	     * divided in proportion to the sales tax and levy rates it includes (e.g. 20% tax in 120 is 20).
226	     */
227	    private BigDecimal includedIn(BigDecimal price, BigDecimal pct) {
228	        BigDecimal grossPct = BigDecimal.valueOf(100).add(taxPct).add(levyPct);
229	        return price.multiply(pct).divide(grossPct, 2, RoundingMode.HALF_UP);
230	    }
231	
232	    public InvoiceStatus getStatus() {
233	        return status;
234	    }
235	
236	    public LocalDate getIssuedDate() {
237	        return issuedDate;
238	    }
239	
