241	        return dueDate;
242	    }
243	
244	    public List<InvoiceLineItem> getLineItems() {
245	        return List.copyOf(lineItems);
246	    }
247	
248	    /** Adds a line to this invoice and reworks its amount to include what the line charges. */
249	    public InvoiceLineItem addLineItem(String description, BigDecimal qty, String unit, BigDecimal unitPrice) {
250	        return addLineItem(description, qty, unit, unitPrice, false, BigDecimal.ZERO);
251	    }
252	
253	    /**
254	     * Adds a line, taxable or tax-free and with any discount of its own, to this invoice and reworks its
255	     * amount to include what the line charges after that discount.
256	     */
257	    public InvoiceLineItem addLineItem(String description, BigDecimal qty, String unit, BigDecimal unitPrice,
258	            boolean taxExempt, BigDecimal discountPct) {
259	        InvoiceLineItem item = new InvoiceLineItem(this, description, qty, unit, unitPrice, taxExempt, discountPct);
260	        lineItems.add(item);
261	        recalculateAmount();
262	        return item;
263	    }
