288	    /** Sets the percentage and the flat amount taken off this invoice and reworks its amount to match. */
289	    public void applyDiscount(BigDecimal discountPct, BigDecimal discountAmount) {
290	        this.discountPct = discountPct.setScale(2, RoundingMode.HALF_UP);
291	        this.discountAmount = discountAmount.setScale(2, RoundingMode.HALF_UP);
292	        recalculateAmount();
293	    }
294	
295	    /** Sets the sales tax percentage added to this invoice and reworks its amount to match. */
296	    public void applyTax(BigDecimal taxPct) {
