310	        recalculateAmount();
311	    }
312	
313	    /** Sets the levy (second tax) percentage added to this invoice and reworks its amount to match. */
314	    public void applyLevy(BigDecimal levyPct) {
315	        this.levyPct = levyPct.setScale(2, RoundingMode.HALF_UP);
316	        recalculateAmount();
317	    }
318	
319	    /**
320	     * The discount taken off one line, to the cent: its percentage, plus its share of the flat amount in
321	     * proportion to what the line charges out of the subtotal.
322	     */
323	    private BigDecimal discountOn(BigDecimal line) {
324	        BigDecimal pct = percentOf(line, discountPct);
325	        BigDecimal subtotal = getSubtotal();
326	        if (subtotal.signum() == 0) {
327	            return pct;
328	        }
329	        BigDecimal flatShare = flatDiscountOn(subtotal).multiply(line).divide(subtotal, 2, RoundingMode.HALF_UP);
330	        return pct.add(flatShare);
331	    }
