333	    /** The flat amount actually taken off the subtotal: never more than is left after the percentage. */
334	    private BigDecimal flatDiscountOn(BigDecimal subtotal) {
335	        BigDecimal left = subtotal.subtract(percentOf(subtotal, discountPct)).max(BigDecimal.ZERO.setScale(2));
336	        return discountAmount.min(left);
337	    }
