342	    }
343	
344	    /** The levy on one discounted taxable line (or inside it, when tax-inclusive), to the cent. */
345	    private BigDecimal levyOn(BigDecimal line) {
346	        return taxInclusive ? includedIn(line, levyPct) : percentOf(line, levyPct);
347	    }
348	
349	    private static BigDecimal percentOf(BigDecimal base, BigDecimal pct) {
350	        return base.multiply(pct).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_UP);
351	    }
