354	        BigDecimal subtotal = getSubtotal();
355	        BigDecimal discounted = subtotal.subtract(getDiscount());
356	        this.amount = taxInclusive ? discounted : discounted.add(getTax()).add(getLevy());
357	    }
358	
359	    /** Marks this invoice as sent to the client. */
360	    public void markSent() {
361	        this.status = InvoiceStatus.SENT;
362	    }
363	
364	    /** Cancels this invoice, so it is no longer owed. */
365	    public void markVoid() {
366	        this.status = InvoiceStatus.VOID;
367	    }
