369	    /** What is left to pay on this invoice given the total paid against it; nothing once it is void. */
370	    public BigDecimal amountDue(BigDecimal paid) {
371	        return status == InvoiceStatus.VOID ? BigDecimal.ZERO.setScale(2) : amount.subtract(paid);
372	    }
