-- An invoice's discount is now either a percentage or a flat amount, never both. An invoice that had
-- both keeps what they took off together, as a flat amount, so its amount is unchanged.
UPDATE invoice i SET
    discount_amount = (
        SELECT ROUND(s.subtotal * i.discount_pct / 100, 2)
            + LEAST(i.discount_amount, GREATEST(s.subtotal - ROUND(s.subtotal * i.discount_pct / 100, 2), 0))
        FROM (SELECT COALESCE(SUM(ROUND(l.qty * l.unit_price, 2)
                    - ROUND(ROUND(l.qty * l.unit_price, 2) * l.discount_pct / 100, 2)), 0) AS subtotal
              FROM invoice_line_item l WHERE l.invoice_id = i.id) s),
    discount_pct = 0
WHERE i.discount_pct > 0 AND i.discount_amount > 0;

ALTER TABLE invoice ADD CONSTRAINT invoice_discount_one_kind CHECK (discount_pct = 0 OR discount_amount = 0);
EOF
